head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.init = function() {
	scwin.setColumnID(window.jsonData1);
};
scwin.makeDataList = function(id, obj) {
	if (scwin.__getObj(id) != undefined) {
		$p.data.remove(id);
	}
	$p.data.create({
		"id": id,
		"type": "dataList",
		"option": {
			"useData": false
		},
		"columnInfo": obj
	});
}
scwin.setColumnID = function(obj) {
	var column = {};
	var columnArr = [];
	var gridHeader = "",
		gridBody = "";
	for (var k in obj[0]) {
		column = {};
		column["id"] = k;
		column["dataType"] = "text";
		columnArr.push(column);
		gridHeader += '<w2:column id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
		gridBody += '<w2:column id="' + k + '" style="height:20px" inputType="text" width="70"></w2:column>'
	}
	scwin.makeDataList('dataList1', columnArr);
	var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" id="gridView1" style="width: 500px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" autoFit="allColumn" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" >' +
		'<w2:header id="header1">' +
		'<w2:row id="row1">' +
		gridHeader +
		'</w2:row>' +
		'</w2:header>' +
		'<w2:gBody id="gBody1">' +
		'<w2:row id="row2">' +
		gridBody +
		'</w2:row>' +
		'</w2:gBody>' +
		'</w2:gridView>';
	gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
	dataList1.setJSON(obj);
}
scwin.setColumnID2 = function() {
	var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" id="gridView1" style="width: 500px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" autoFit="allColumn" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" ><w2:header id="header1"><w2:row id="row1"><w2:column id="hcol0" style="height:20px" inputType="text" width="70" value="col0" useFilter="true"></w2:column><w2:column id="hcol1" style="height:20px" inputType="text" width="70" value="col1" useFilter="true"></w2:column><w2:column id="hcol2" style="height:20px" inputType="text" width="70" value="col2" useFilter="true"></w2:column><w2:column id="hcol3" style="height:20px" inputType="text" width="70" value="col3" useFilter="true"></w2:column></w2:row></w2:header><w2:gBody id="gBody1"><w2:row id="row2"><w2:column id="col0" style="height:20px" inputType="text" width="70"></w2:column><w2:column id="col1" style="height:20px" inputType="text" width="70"></w2:column><w2:column id="col2" style="height:20px" inputType="text" width="70"></w2:column><w2:column id="col3" style="height:20px" inputType="text" width="70"></w2:column></w2:row></w2:gBody></w2:gridView>';
	gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
}
scwin.trigger1_onclick = function(e) {
	scwin.setColumnID2();
};
scwin.checkEl = function(id) {
	if (scwin.__getDom($p.id + id)) {
		return true;
	}
	return false;
}
scwin.onpageload = function() {
	window.jsonData1 = [{
		"col0": "0",
		"col1": "test",
		"col2": "test",
		"col3": "test"
	}, {
		"col0": "1",
		"col1": "test",
		"col2": "test2",
		"col3": "test"
	}, {
		"col0": "1",
		"col1": "test",
		"col2": "test",
		"col3": "test"
	}, {
		"col0": "1",
		"col1": "test",
		"col2": "test",
		"col3": "test"
	}];
	scwin.init();
};
